function fetchNewUserData(a,e,s){var i=moment().utc().subtract(e,"seconds").format();$.ajax({url:"/lib/webservices/usersFeed.php",type:"POST",dataType:"json",data:"hotel_id="+a+"&from="+i+"&getUsersFeed=true&usersNum="+s,success:function(e){e&&(e.reverse(),e.forEach(function(e){var a=moment.parseZone(e.last_login).local().format();e.sexo||(e.sexo="male"),e.facebook_img?(e.img=e.facebook_img,e.source="facebook",e.icon="facebook square"):(e.source="form",e.icon="wpforms",e.img="/public/images/"+e.sexo+"_avatar_placeholder.svg"),$(".feed").prepend('<div class="ui segment event bg" style="padding:1rem 2rem; background: white; margin-bottom:.4rem; display: none"><div class="label"><img src="'+e.img+'"></div><div class="content"><div class="summary"><a class="user">'+e.nombre+'</a> Connected with your hotel<div class="date">'+moment(a).fromNow()+'</div></div><div class="meta"><div class="ui horizontal bulleted link list"><a class="item">'+e.location+'</a><a class="item"><i class="'+e.icon+' icon"></i> From '+e.source+'</a> <a class="item"><i class="birthday cake icon"></i> '+e.fecha_nacimiento+"</a></div></div></div></div>"),$(".event:first-child").transition("fly down")}))},complete:function(e){setTimeout(fetchNewUserData,6e4,a,60,null)}})}